export interface StatusPanel {
  kind: string;
  title: string;
  theme: string;
  primary: string;
  secondary: string;
  icon: string;
  tags: string[];
  values: number[];
}

export type StatusPanelInput = Partial<StatusPanel> & Pick<StatusPanel, "kind">;

const EMPTY_TAGS: string[] = [];

export function createStatusPanel(input: StatusPanelInput): StatusPanel {
  if (input === null || typeof input !== "object") {
    throw new TypeError("input must be an object");
  }
  if (typeof input.kind !== "string" || input.kind.trim().length === 0) {
    throw new TypeError("kind must contain non-whitespace characters");
  }
  if (input.tags !== undefined && (!Array.isArray(input.tags) || input.tags.some((tag) => typeof tag !== "string"))) {
    throw new TypeError("tags must contain only strings");
  }
  if (input.values !== undefined && (!Array.isArray(input.values) || input.values.some((value) => !Number.isFinite(value)))) {
    throw new TypeError("values must contain only finite numbers");
  }
  return {
    kind: input.kind,
    title: input.title ?? "",
    theme: input.theme ?? "neutral",
    primary: input.primary ?? "N/A",
    secondary: input.secondary ?? "N/A",
    icon: input.icon ?? "circle",
    tags: input.tags === undefined ? EMPTY_TAGS : [...input.tags],
    values: input.values === undefined ? [] : [...input.values],
  };
}
```

