import { createStatusPanel, StatusPanel, StatusPanelInput } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof TypeError, message); return; }
  throw new Error(`${message}: did not throw`);
}
function panelDefaults(panel: StatusPanel, kind: string): void {
  equal(panel.kind, kind, 'kind');
  equal(panel.title, '', 'default title');
  equal(panel.theme, 'neutral', 'default theme');
  equal(panel.primary, 'N/A', 'default primary');
  equal(panel.secondary, 'N/A', 'default secondary');
  equal(panel.icon, 'circle', 'default icon');
  equal(panel.tags.length, 0, 'default tags');
  equal(panel.values.length, 0, 'default values');
}

const minimal = createStatusPanel({ kind: ' status ' });
panelDefaults(minimal, ' status ');
const another = createStatusPanel({ kind: 'other' });
assert(minimal !== another, 'result objects are fresh');
assert(minimal.tags !== another.tags, 'default tag arrays are not shared');
assert(minimal.values !== another.values, 'default value arrays are not shared');
minimal.tags.push('mutation');
equal(another.tags.length, 0, 'default tag mutation isolated');

const input: StatusPanelInput = {
  kind: 'k', title: '', theme: '', primary: '', secondary: '', icon: '',
  tags: ['a', ''], values: [0, -2.5],
};
const panel = createStatusPanel(input);
equal(panel.title, '', 'empty title preserved');
equal(panel.theme, '', 'empty theme preserved');
equal(panel.primary, '', 'empty primary preserved');
equal(panel.secondary, '', 'empty secondary preserved');
equal(panel.icon, '', 'empty icon preserved');
equal(panel.tags.join('|'), 'a|', 'tags preserved');
equal(panel.values.join('|'), '0|-2.5', 'values preserved');
assert(panel.tags !== input.tags, 'tags copied');
assert(panel.values !== input.values, 'values copied');
input.tags![0] = 'changed';
input.values![0] = 99;
equal(panel.tags[0], 'a', 'input tag mutation isolated');
equal(panel.values[0], 0, 'input value mutation isolated');

throwsType(() => createStatusPanel(null as unknown as StatusPanelInput), 'null input');
throwsType(() => createStatusPanel(3 as unknown as StatusPanelInput), 'primitive input');
for (const kind of ['', ' ', '\t\n', 3 as unknown as string]) {
  throwsType(() => createStatusPanel({ kind }), 'invalid kind');
}
throwsType(() => createStatusPanel({ kind: 'k', tags: null as unknown as string[] }), 'null tags');
throwsType(() => createStatusPanel({ kind: 'k', tags: ['ok', 2 as unknown as string] }), 'non-string tag');
throwsType(() => createStatusPanel({ kind: 'k', values: null as unknown as number[] }), 'null values');
for (const value of [NaN, Infinity, -Infinity]) {
  throwsType(() => createStatusPanel({ kind: 'k', values: [value] }), 'non-finite value');
}

